export function CodeBlock({
  code = "{{code}}",
  language = "{{language}}",
  showLineNumbers = {{showLineNumbers}},
  accent = "{{accent}}",
  radius = {{radius}},
}) {
  return (
    <div style={{ fontFamily: "SFMono-Regular, Consolas, 'Liberation Mono', monospace", fontSize: 13,
      lineHeight: 1.6, background: "#241430", color: "#FAF7F2", overflow: "hidden", maxWidth: 460, borderRadius: radius }}>
      <div style={{ display: "flex", alignItems: "center", gap: 10, padding: "8px 12px", borderBottom: "1px solid #ffffff1a" }}>
        <span aria-hidden="true" style={{ display: "inline-flex", gap: 5 }}>
          {[0, 1, 2].map((i) => <i key={i} style={{ width: 8, height: 8, borderRadius: "50%", background: "#ffffff26", display: "inline-block" }} />)}
        </span>
        <span style={{ marginLeft: "auto", fontFamily: "system-ui, sans-serif", fontSize: 11, fontWeight: 600,
          letterSpacing: ".04em", textTransform: "uppercase", color: accent }}>{language}</span>
      </div>
      <div style={{ display: "flex" }}>
        {showLineNumbers && <span aria-hidden="true" style={{ padding: "14px 0 14px 14px", color: "#ffffff40", userSelect: "none" }}>1</span>}
        <pre style={{ margin: 0, padding: "14px 16px", overflowX: "auto", whiteSpace: "pre", flex: 1 }}><code>{code}</code></pre>
      </div>
    </div>
  );
}
